<script setup>
import MobileDialog from './MobileDialog.vue';
import MobileStocktakeDialog from './MobileStocktakeDialog.vue';
import {computed,nextTick,onBeforeUnmount,reactive,ref,watch} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import {apiClient,currentApiCacheScope} from '../../utils/api.js';
import {useAuthStore} from '../../stores/auth.js';
import {PROCUREMENT_PRICE_REASONS,procurementPriceReason} from '../../../../src/shared/procurement-price-reason.js';
import {purchaseLink} from '../../utils/mobile-evidence.js';
import {inventorySearchDefaults,appendInventorySearch} from '../../../../src/shared/inventory-search-fields.js';
import MobileInventorySearch from './MobileInventorySearch.vue';
import MobilePagination from './MobilePagination.vue';
import InventoryCompositionBadge from '../inventory/InventoryCompositionBadge.vue';
import MobileEvidencePicker from './MobileEvidencePicker.vue';
import ProductImagePreview from '../ProductImagePreview.vue';
const props=defineProps({modelValue:Boolean,initialRows:{type:Array,default:()=>[]}}),emit=defineEmits(['update:modelValue','saved']);const auth=useAuthStore();
const visible=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)}),items=ref([]),results=ref([]),filters=reactive({...inventorySearchDefaults(),searchMode:'inventory_id',query:'',inventoryType:'all'}),searchPage=ref(1),searchPageSize=ref(20),searchTotal=ref(0),searched=ref(false),busy=ref(false),searching=ref(false),error=ref(''),receipts=ref([]),photoState=ref({busy:false,ready:true}),submitted=ref(null);
const resultsOpen=ref(false),previewProduct=ref(null),purchaseRoot=ref(null);
const form=reactive({source_type:'1688',platform_order_no:'',tracking_number:'',courier_company:'',note:''});let generation=0,searchVersion=0,disposed=false,key='';
const total=computed(()=>items.value.reduce((s,r)=>s+Number(r.amount||0)+Number(r.shipping_amount||0),0).toFixed(2));
function physical(row,quantity){const id=Number(row.product_id||row.id);if(items.value.some(r=>r.product_id===id))return;if(items.value.length>=50)throw Error('一次最多50项，请分批登记');const p=row.workflow?.supply_plan;items.value.push({product_id:id,name:row.product_name||row.name,number:row.inventory_number||row.code,quantity:quantity??Math.max(1,Number(p?.required_purchase||0)+Number(p?.optional_purchase||0)),amount:null,shipping_amount:0,purchase_url:row.purchase_url||'',note:'',anomaly_reason:'',anomaly_note:''});}
async function add(row){const token=generation,scope=currentApiCacheScope();try{if(row.workflow||(row.component_count!=null&&Number(row.component_count)===0)){physical(row);return;}const r=await apiClient.get(`/api/inventory-workflow?view=components&product_id=${Number(row.product_id||row.id)}`,{noCache:true});if(disposed||token!==generation||scope!==currentApiCacheScope())return;const composition=r.rows?.[0];if(!composition?.components?.length)throw Error('库存组成未读取完整，请重试');if(composition.is_bundle){if(items.value.length+composition.components.length>50)throw Error('套装展开后超过50项，请分批采购');for(const part of composition.components)physical(part,Number(part.per_set_quantity));ElMessage.info('套装已展开为实物商品，请填写本次各配件实际采购数');}else physical(row);}catch(e){if(token===generation&&scope===currentApiCacheScope())error.value=e.message;}}
async function search(reset=false){blurKeyboard();resultsOpen.value=true;if(reset)searchPage.value=1;const token=++searchVersion,scope=currentApiCacheScope();searching.value=true;error.value='';try{const params=appendInventorySearch(new URLSearchParams({paged:'1',view:'inventory',includeStock:'0',page:String(searchPage.value),pageSize:String(searchPageSize.value),query:filters.query.trim(),inventoryType:filters.inventoryType}),filters);const r=await apiClient.get('/api/products?'+params,{noCache:true});if(!disposed&&token===searchVersion&&scope===currentApiCacheScope()){results.value=r.rows||[];searchTotal.value=Number(r.total||0);searched.value=true;}}catch(e){if(token===searchVersion&&scope===currentApiCacheScope())error.value=e.message;}finally{if(token===searchVersion)searching.value=false;}}
function resetSearch(){Object.assign(filters,inventorySearchDefaults(),{searchMode:'inventory_id',query:'',inventoryType:'all'});search(true);}
function changeSearchPage(value){searchPage.value=value.page;searchPageSize.value=value.pageSize;search();}

function blurKeyboard(){const field=document.activeElement;if(purchaseRoot.value?.closest('.mobile-purchase-dialog')?.contains(field))field.blur?.();}
async function revealFocusedField(){await nextTick();const field=document.activeElement,root=purchaseRoot.value;if(!root?.contains(field))return;const content=root.closest('.mobile-dialog-content');if(!content)return;const rect=field.getBoundingClientRect(),area=content.getBoundingClientRect();if(rect.bottom>area.bottom-16)content.scrollTop+=rect.bottom-area.bottom+16;else if(rect.top<area.top+12)content.scrollTop-=area.top+12-rect.top;}
async function showSelected(id){blurKeyboard();resultsOpen.value=false;await nextTick();const root=purchaseRoot.value,card=id?root?.querySelector(`[data-purchase-product="${Number(id)}"]`):root?.querySelector('.mobile-purchase-selected');card?.scrollIntoView({block:'start'});}
async function choose(row){if(busy.value||submitted.value)return;const before=items.value.length;blurKeyboard();await add(row);if(items.value.length>before)await showSelected(items.value[before].product_id);}
window.visualViewport?.addEventListener('resize',revealFocusedField);

async function save(){if(busy.value)return;if(!photoState.value.ready||photoState.value.busy)return ElMessage.warning('请等待凭证上传完成，失败的照片请重试或移除');if(!items.value.length)return ElMessage.warning('请先搜索并添加采购商品');error.value='';if(!submitted.value){try{for(const row of items.value){if(!Number.isSafeInteger(Number(row.quantity))||Number(row.quantity)<1||!(Number(row.amount)>0)||!Number.isFinite(Number(row.amount))||Number(row.shipping_amount)<0||!Number.isFinite(Number(row.shipping_amount)))throw Error(`请核对「${row.name}」的数量、货款和运费`);}submitted.value={mobile_input:true,workspace_batch:true,request_key:key,person_id:Number(auth.user?.personId||auth.user?.id),...form,receipts:[...receipts.value],items:items.value.map(r=>({product_id:r.product_id,quantity:Number(r.quantity),actual_quantity:Number(r.quantity),amount:Number(r.amount),shipping_amount:Number(r.shipping_amount),purchase_mode:'shortage_purchase',purchase_url:purchaseLink(r.purchase_url),note:r.note,anomaly_reason:procurementPriceReason(r)}))};}catch(e){submitted.value=null;return ElMessage.warning(e.message);}}
 const token=generation,scope=currentApiCacheScope();busy.value=true;try{const r=await apiClient.post('/api/procurement/purchases',submitted.value);if(disposed||token!==generation||scope!==currentApiCacheScope())return;ElMessage.success('采购已登记，进入采购在途');emit('saved',r);visible.value=false;}catch(e){if(token===generation&&scope===currentApiCacheScope()){error.value=e.message+'；表单已保留。';if([400,403,404,409].includes(e.status))submitted.value=null;}}finally{if(token===generation)busy.value=false;}}
async function close(done){if(busy.value||photoState.value.busy)return;if(items.value.length){try{await ElMessageBox.confirm('关闭后将放弃尚未登记的采购内容。','关闭采购表',{confirmButtonText:'放弃并关闭',cancelButtonText:'继续填写'});}catch{return;}}done();}
function clear(){resultsOpen.value=false;previewProduct.value=null;++generation;++searchVersion;items.value=[];results.value=[];receipts.value=[];submitted.value=null;visible.value=false;}
watch(()=>props.modelValue,async v=>{if(!v){resultsOpen.value=false;previewProduct.value=null;++generation;++searchVersion;return;}++generation;items.value=[];results.value=[];receipts.value=[];submitted.value=null;photoState.value={busy:false,ready:true};Object.assign(filters,inventorySearchDefaults(),{searchMode:'inventory_id',query:'',inventoryType:'all'});searchPage.value=1;searchPageSize.value=20;searchTotal.value=0;searched.value=false;error.value='';key=crypto.randomUUID();Object.assign(form,{source_type:'1688',platform_order_no:'',tracking_number:'',courier_company:'',note:''});for(const r of props.initialRows)await add(r);},{immediate:true});window.addEventListener('erp:auth-scope-changed',clear);onBeforeUnmount(()=>{window.visualViewport?.removeEventListener('resize',revealFocusedField);disposed=true;clear();window.removeEventListener('erp:auth-scope-changed',clear);});
</script>
<template>
 <MobileDialog v-model="visible" class="mobile-purchase-dialog" title="登记实际采购" :before-close="close" :show-close="!busy" :close-on-press-escape="false">
  <template v-if="!submitted" #tools><MobileInventorySearch :filters="filters" :loading="searching" @search="search(true)" @reset="resetSearch"><template #actions><el-button @click="showSelected()">已选 {{items.length}}</el-button></template></MobileInventorySearch></template>
  <div ref="purchaseRoot" class="mobile-form mobile-purchase-body" @focusin="revealFocusedField">
   <el-alert v-if="error" :title="error" type="warning" :closable="false"/>
   <section v-if="resultsOpen&&!submitted" class="mobile-purchase-results" aria-label="库存搜索结果">
    <div class="mobile-purchase-section-heading"><strong>搜索结果</strong><el-button @click="resultsOpen=false">收起结果</el-button></div>
    <p v-if="searching" class="mobile-muted">正在查找库存…</p>
    <div v-else class="mobile-purchase-results-list"><article v-for="r in results" :key="r.id" class="mobile-record"><div class="mobile-record-head"><ProductImagePreview :src="`/api/products/${r.id}/image?thumb=1`" size="portrait"/><div><b>{{r.name}}</b><small>库存 {{r.inventory_number||r.code||r.id}} · {{Number(r.component_count)>0?'套装':Number(r.is_accessory)?'配件':'单品'}}</small><el-button link @click="previewProduct=r">库存详情</el-button></div></div><el-button :disabled="busy||items.some(i=>i.product_id===Number(r.id))" type="primary" @click="choose(r)">{{items.some(i=>i.product_id===Number(r.id))?'已添加':'加入采购'}}</el-button></article><p v-if="searched&&!results.length" class="mobile-muted">未找到商品，请调整库存ID或精确搜索条件。</p></div>
    <MobilePagination v-if="searched" :page="searchPage" :page-size="searchPageSize" :total="searchTotal" :loading="searching" @change="changeSearchPage"/>
   </section>
   <section class="mobile-purchase-selected" aria-label="本次采购商品">
    <div class="mobile-purchase-section-heading"><strong>本次采购 · {{items.length}} 项</strong><small class="mobile-muted">采购人 {{auth.user?.name||auth.user?.username}}</small></div>
    <p v-if="!items.length" class="mobile-muted">在上方输入库存ID，查询后直接加入采购，无需切换页面。</p>
    <article v-for="row in items" :key="row.product_id" :data-purchase-product="row.product_id" class="mobile-record">
     <div class="mobile-record-head"><ProductImagePreview :src="`/api/products/${row.product_id}/image?thumb=1`" size="portrait"/><div><h3>{{row.name}}</h3><small>库存 {{row.number||row.product_id}}</small></div><el-button type="danger" plain :disabled="busy||!!submitted" @click="items=items.filter(i=>i!==row)">移除</el-button></div>
     <div class="mobile-form-pair"><label>采购件数<input v-model.number="row.quantity" aria-label="实际采购件数" type="number" inputmode="numeric" min="1" step="1" :disabled="busy||!!submitted"></label><label>货款（元，不含运费）<input v-model.number="row.amount" aria-label="采购货款" type="number" inputmode="decimal" min="0" step="0.01" :disabled="busy||!!submitted"></label></div>
     <details class="mobile-purchase-extra" :open="!!error||!!row.anomaly_reason"><summary>运费、采购链接与价格变动原因</summary><div class="mobile-form"><label>运费（元）<input v-model.number="row.shipping_amount" aria-label="采购运费" type="number" inputmode="decimal" min="0" step="0.01" :disabled="busy||!!submitted"></label><label>采购链接<input v-model="row.purchase_url" placeholder="粘贴采购链接或分享文字" maxlength="2000" :disabled="busy||!!submitted"></label><label>价格变动原因（上涨超过10%时必填）<select v-model="row.anomaly_reason" :disabled="busy||!!submitted"><option value="">未选择</option><option v-for="reason in PROCUREMENT_PRICE_REASONS" :key="reason">{{reason}}</option></select></label><label v-if="row.anomaly_reason==='其他原因'">具体原因<input v-model="row.anomaly_note" maxlength="300" :disabled="busy||!!submitted"></label></div></details>
    </article>
   </section>
   <details class="mobile-purchase-extra"><summary>采购平台：{{form.source_type==='1688'?'1688':form.source_type==='pdd'?'拼多多':form.source_type==='taobao'?'淘宝':'其他'}} · 订单号、快递与凭证</summary><div class="mobile-form"><label>采购平台<select v-model="form.source_type" :disabled="busy||!!submitted"><option value="1688">1688</option><option value="pdd">拼多多</option><option value="taobao">淘宝</option><option value="other">其他</option></select></label><label>采购订单号<input v-model="form.platform_order_no" placeholder="粘贴采购平台订单号" maxlength="128" :disabled="busy||!!submitted"></label><label>快递单号<input v-model="form.tracking_number" placeholder="粘贴快递单号，可后补" maxlength="128" :disabled="busy||!!submitted"></label><label>备注<textarea v-model="form.note" maxlength="500" :disabled="busy||!!submitted"/></label><MobileEvidencePicker v-model="receipts" label="采购截图" :disabled="busy||!!submitted" @state="photoState=$event"/></div></details>
   <small class="mobile-muted">仅登记已下单采购，验收入库前不增加本地实物。</small><small v-if="submitted" class="mobile-muted">正在核对上次提交结果，重试不会重复登记。</small>
  </div>
  <template #footer><el-button :disabled="busy||photoState.busy" @click="close(()=>visible=false)">取消</el-button><span class="mobile-purchase-total">{{items.length}}项 · ¥{{total}}</span><el-button :loading="busy" :disabled="!photoState.ready||photoState.busy||!items.length" type="primary" @click="save">确认登记</el-button></template>
 </MobileDialog>
 <MobileStocktakeDialog v-if="previewProduct" :model-value="!!previewProduct" :product="previewProduct" read-only @update:model-value="v=>{if(!v)previewProduct=null}"/>
</template>
<style scoped>
.mobile-purchase-body{scroll-padding:16px;min-width:0}.mobile-purchase-selected{display:grid;gap:10px;min-width:0}.mobile-purchase-section-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0}.mobile-purchase-section-heading strong{font-size:14px}.mobile-purchase-results{min-width:0;display:grid;gap:8px;padding:10px;border:1px solid var(--el-border-color-light);border-radius:10px;background:var(--el-fill-color-extra-light)}.mobile-purchase-results-list{max-height:min(40dvh,320px);overflow:auto;display:grid;gap:8px;overscroll-behavior:contain}.mobile-purchase-results .mobile-record-head b{font-size:13px;overflow-wrap:anywhere}.mobile-purchase-results :deep(.mobile-list-footer){background:transparent}.mobile-purchase-extra{min-width:0;font-size:13px}.mobile-purchase-extra summary{padding:10px 0;min-height:24px;cursor:pointer;color:var(--el-color-primary);line-height:1.6;overflow-wrap:anywhere}.mobile-purchase-extra>.mobile-form{padding-top:6px}.mobile-purchase-total{flex:1;min-width:0;text-align:center;font-size:13px;font-variant-numeric:tabular-nums}.mobile-purchase-body .mobile-record-head>.el-button{flex:none;padding:8px}.mobile-purchase-body input,.mobile-purchase-body textarea{scroll-margin-block:16px}
</style>
